import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as o}from"./chunks/M-S-HDS-WF-Scr.ATovYKe5.js";import{_ as r,o as a,c as s,a3 as i}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Libre Web Follower","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshoot/webfollow.md","filePath":"troubleshoot/webfollow.md"}'),n={name:"troubleshoot/webfollow.md"};function l(p,e,d,h,c,u){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="libre-web-follower" tabindex="-1">Libre Web Follower <a class="header-anchor" href="#libre-web-follower" aria-label="Permalink to &quot;Libre Web Follower&quot;">​</a></h1><h2 id="system-setup" tabindex="-1">System setup <a class="header-anchor" href="#system-setup" aria-label="Permalink to &quot;System setup&quot;">​</a></h2><p>When using this data source you need to make sure your system is configured correctly with the vendor apps.</p><p><strong>The master app (connected to the Libre sensor) should upload data to the vendor <a href="https://www.libreview.com/" target="_blank" rel="noreferrer">server</a>.</strong></p><p>Log out and in to the server to verify you are using the right credentials.</p><p>Make sure you have data in the server.</p><p><strong>The vendor <a href="https://play.google.com/store/search?q=librelinkup&amp;c=apps" target="_blank" rel="noreferrer">follower</a> app should receive shared data.</strong></p><p>Try to delete and resend an invitation to the vendor follower app (using the vendor master app).</p><p>Try to uninstall and reinstall the vendor follower app.</p><ul><li>Use preferably the set of credentials from the invitation to log in.</li><li>If it doesn&#39;t work use the master app (server) credentials and resend the invitation.</li></ul><br><h2 id="xdrip-setup" tabindex="-1">xDrip setup <a class="header-anchor" href="#xdrip-setup" aria-label="Permalink to &quot;xDrip setup&quot;">​</a></h2><p>Once the system is running on the vendor apps, you can troubleshoot xDrip.</p><ol><li>Make sure the data source is <a href="./../install/webfollower.html">Web follower</a>.</li><li>Use the credentials from the follower you invited with the vendor master app.</li><li>If it doesn&#39;t work, you can try to use the server credentials to troubleshoot, but be cautious to reduce the risks of an account lock.</li></ol><br><h2 id="vendor-servers-updates" tabindex="-1">Vendor servers updates <a class="header-anchor" href="#vendor-servers-updates" aria-label="Permalink to &quot;Vendor servers updates&quot;">​</a></h2><p>Server updates might break the mechanism.</p><p><strong>Once xDrip has been fixed</strong>, you might need to reset it following this sequence:</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Settings<br>  Hardware Data Source<br>   Web Follower</p></div><p>Edit the <code>Configuration script</code></p><div class="admonition xdripitem"><p class="admonition-title">Configuration Script</p><p> This is the community helper address or keyword</p></div><p>Add a space after <code>beonlabs</code>, select <code>Ok</code></p><img src="'+o+'" style="zoom:75%;"><p>Edit again the <code>Configuration script</code>, <strong>remove the space</strong> after <code>beonlabs</code>, and select <code>Ok</code>.</p><p>Wait up to a minute for data to display again.</p><br><p>If the issue persists, install the vendor follower app on the same phone and check it can receive data with the same credentials.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Last modified 8/12/2024</em></a></p>',29)])])}const g=r(n,[["render",l]]);export{v as __pageData,g as default};
